66	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Returns {@code UNKNOWN}
67	     * when the city is absent or not in the table.
68	     */
69	    default String cityRegion(Owner owner) {
70	        String city = owner.getCity();
71	        if (city == null) {
72	            return "UNKNOWN";
73	        }
74	        switch (city) {
75	            case "Sydney":
76	                return "NSW";
77	            case "Melbourne":
78	                return "VIC";
79	            case "Brisbane":
80	                return "QLD";
81	            default:
82	                return "UNKNOWN";
83	        }
84	    }
