87	     * Resolves the region from the owner's 4-digit postcode range, or {@code null}
88	     * when the postcode is absent, malformed, or in no known range.
89	     */
90	    default String regionFromPostcode(Owner owner) {
91	        String postcode = owner.getPostcode();
92	        if (postcode == null) {
93	            return null;
94	        }
95	        int code;
96	        try {
