101	        }
102	        if (code >= 2000 && code <= 2099) {
103	            return "NSW";
104	        }
105	        if (code >= 3000 && code <= 3099) {
106	            return "VIC";
107	        }
108	        if (code >= 4000 && code <= 4099) {
109	            return "QLD";
