116	     * an email is present, gains 1 when {@code namesakeCount} is 0, and is capped at 3 (level 4 is
117	     * reserved for tenure).
118	     */
119	    default Integer membershipLevel(Owner owner) {
120	        int level = 1;
121	        String email = owner.getEmail();
122	        if (email != null && !email.isEmpty()) {
123	            level++;
124	        }
125	        Integer namesakeCount = owner.getNamesakeCount();
126	        if (namesakeCount != null && namesakeCount == 0) {
127	            level++;
128	        }
129	        return Math.min(level, 3);
130	    }
