132	    /**
133	     * Builds the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;'
134	     * where YY is the last two digits of the registrationDate year. Returns {@code null}
135	     * when either source field is absent.
136	     */
137	    default String membershipNumber(Owner owner) {
138	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
139	            return null;
140	        }
141	        return owner.getCustomerCode() + "-M"
142	            + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
