147	     * owner's customerCode. Non-digit characters are ignored. Returns {@code null}
148	     * when the customerCode is absent.
149	     */
150	    default Integer checkDigit(Owner owner) {
151	        String customerCode = owner.getCustomerCode();
152	        if (customerCode == null) {
153	            return null;
154	        }
155	        int sum = 0;
156	        boolean dbl = true;
157	        for (int i = customerCode.length() - 1; i >= 0; i--) {
158	            char c = customerCode.charAt(i);
159	            if (c < '0' || c > '9') {
160	                continue;
161	            }
162	            int d = c - '0';
163	            if (dbl) {
164	                d *= 2;
165	                if (d > 9) {
